def dialogue_translations(language):
    bank = ZH if language == 'zh_cn' else EN
    result = {f'dialogue.toneko.mushroom_girl.{category}.{i}': line
              for category, lines in bank.items() for i, line in enumerate(lines)}
    zh = language == 'zh_cn'
    labels = {
        'growth': ('等级：%s · 经验：%s / %s', 'Level: %s · XP: %s / %s'),
        'growth_max': ('等级：%s · 已满级', 'Level: %s · Maximum level'),
        'growth_stats': ('生命：%s / %s · 孢子伤害：%s', 'Health: %s / %s · Spore damage: %s'),
        'affection': ('好感度（%s）：%s / 100', 'Affection (%s): %s / 100'),
        'relationship_help': ('熟悉100后开启好感 · 好感20起主动靠近', 'Full familiarity unlocks affection; 20 unlocks visits'),
        'companion': ('陪伴互动', 'Companion actions'),
        'companion_help': ('背起60：站着就能直接背起', 'Carry 60: works while standing'),
        'bed_help': ('睡床60自动陪伴 · 地面坐/趴80先躺下', 'Bed 60: automatic company · Ground sit / lie 80: lie down first'),
        'bed_wake_help': ('床上醒来继续躺着，按 Shift 主动起身', 'Stay lying after waking in bed; press Shift to stand'),
        'carry': ('背在身上', 'Carry on your back'),
        'carry.des': ('无需躺下；熟悉度60后，站着即可背起她。', 'No lying down needed. At familiarity 60, carry her while standing.'),
        'sit_on_player': ('坐在我身上', 'Sit on me'),
        'sit_on_player.des': ('床上熟悉度60，地面躺卧熟悉度80。', 'Familiarity 60 in bed, or 80 while lying on the ground.'),
        'lie_on_player': ('趴在我身上', 'Lie on me'),
        'lie_on_player.des': ('先躺下；床上熟悉度60，地面熟悉度80。', 'Lie down first. Familiarity 60 in bed, or 80 on the ground.'),
        'get_down': ('让她下来', 'Let her down'),
        'get_down.des': ('结束陪伴；床上停留可以按 Shift 起身。', 'End companionship. Press Shift to stand up from a bed rest.'),
    }
    result.update({f'screen.toneko.mushroom_girl.{key}': pair[0 if zh else 1] for key, pair in labels.items()})
    result['message.toneko.mushroom_girl.lie_first'] = '先用 /neko lie 躺下，再邀请她陪伴。' if zh else 'Lie down with /neko lie before inviting her to join you.'
    result['message.toneko.mushroom_girl.companion_unavailable'] = '先靠近她，留出空位，在水外安全的地方再试试吧。' if zh else 'Come closer, make room, and try again in a safe spot out of the water.'
    result['message.toneko.mushroom_girl.affection_unlocked'] = '%s：「你的气息已经很熟悉啦……以后，也想多陪你一点。」好感度阶段已开启。' if zh else '%s: "I know you well now... I would like to stay with you a little longer." Affection is now unlocked.'
    for key, pair in {'fond': ('亲近', 'Fond'), 'close': ('亲密', 'Close'), 'attached': ('依恋', 'Attached')}.items():
        result['stage.toneko.mushroom_girl.' + key] = pair[0 if zh else 1]
    return result
